package com.mohymods.kingdomsmp.profession;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
/** Immutable prior authorization in the canonical Root journal, never an instruction to modify blocks. */
public record MineExcavationSite(UUID id,UUID admin,UUID player,String dimension,BlockPos from,BlockPos to,String surroundings,String reason){
 public MineExcavationSite{Objects.requireNonNull(id);Objects.requireNonNull(admin);Objects.requireNonNull(player);from=Objects.requireNonNull(from).immutable();to=Objects.requireNonNull(to).immutable();if(!"minecraft:overworld".equals(dimension))throw new IllegalArgumentException("Excavation belongs in the Overworld");long x=(long)to.getX()-from.getX()+1,y=(long)to.getY()-from.getY()+1,z=(long)to.getZ()-from.getZ()+1;if(x<2||x>8||y<2||y>8||z<2||z>8||Math.abs((long)from.getX())>=30000000||Math.abs((long)to.getX())>=30000000||Math.abs((long)from.getZ())>=30000000||Math.abs((long)to.getZ())>=30000000||from.getY()<-2048||to.getY()>2047)throw new IllegalArgumentException("Ordered excavation dimensions must each be2..8blocks within world limits");if(surroundings==null||!surroundings.matches("[0-9a-f]{64}")||reason==null||reason.length()<12||reason.length()>96||reason.chars().anyMatch(Character::isISOControl))throw new IllegalArgumentException("Record a valid surroundings snapshot and12..96character purpose/consent");}
 public int volume(){return (to.getX()-from.getX()+1)*(to.getY()-from.getY()+1)*(to.getZ()-from.getZ()+1);}
 public boolean contains(BlockPos p){return p.getX()>=from.getX()&&p.getX()<=to.getX()&&p.getY()>=from.getY()&&p.getY()<=to.getY()&&p.getZ()>=from.getZ()&&p.getZ()<=to.getZ();}
 public CompoundTag save(){var t=new CompoundTag();t.putUUID("id",id);t.putUUID("admin",admin);t.putUUID("player",player);t.putString("dimension",dimension);t.putLong("from",from.asLong());t.putLong("to",to.asLong());t.putString("surroundings",surroundings);t.putString("reason",reason);return t;}
 public static MineExcavationSite load(CompoundTag t){if(!t.getAllKeys().equals(Set.of("id","admin","player","dimension","from","to","surroundings","reason"))||!t.hasUUID("id")||!t.hasUUID("admin")||!t.hasUUID("player")||!t.contains("dimension",Tag.TAG_STRING)||!t.contains("from",Tag.TAG_LONG)||!t.contains("to",Tag.TAG_LONG)||!t.contains("surroundings",Tag.TAG_STRING)||!t.contains("reason",Tag.TAG_STRING))throw new IllegalArgumentException("Malformed excavation authorization");return new MineExcavationSite(t.getUUID("id"),t.getUUID("admin"),t.getUUID("player"),t.getString("dimension"),BlockPos.of(t.getLong("from")),BlockPos.of(t.getLong("to")),t.getString("surroundings"),t.getString("reason"));}
}
